def calculate_factorial(n: int) -> int:
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 1

    result: int = 1
    for i in range(1, n + 1):
        result *= i
    return result

def test_factorials() -> None:
    test_cases: list[tuple[int, int]] = [
        (0, 1),
        (1, 1),
        (2, 2),
        (3, 6),
        (4, 24),
        (5, 120),
        (10, 3628800)
    ]

    for input_n, expected_output in test_cases:
        actual_output: int = calculate_factorial(input_n)
        assert actual_output == expected_output, f"For n={input_n}, expected {expected_output}, got {actual_output}"
        print(f"Test passed for n={input_n}")

def main() -> None:
    test_factorials()
    numbers_to_calculate: list[int] = [0, 1, 6, 7]
    for num in numbers_to_calculate:
        fact: int = calculate_factorial(num)
        print(f"The factorial of {num} is {fact}")

if __name__ == "__main__":
    main()

