import math

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i: int = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_primes_in_range(start: int, end: int) -> list[int]:
    primes: list[int] = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

def check_prime_examples() -> dict[int, bool]:
    examples: dict[int, bool] = {
        2: True, 3: True, 4: False, 5: True, 7: True, 10: False, 11: True, 13: True, 17: True, 20: False
    }
    results: dict[int, bool] = {}
    for num, expected in examples.items():
        results[num] = is_prime(num)
        assert results[num] == expected, f"Test failed for {num}: Expected {expected}, got {results[num]}"
    return results

if __name__ == "__main__":
    check_prime_examples()
    print(f"Is 7 prime? {is_prime(7)}")
    print(f"Is 10 prime? {is_prime(10)}")
    print(f"Primes between 1 and 20: {get_primes_in_range(1, 20)}")
    range_check: list[int] = get_primes_in_range(90, 100)
    print(f"Primes between 90 and 100: {range_check}")

