def merge_dictionaries(dict1: dict[str, int], dict2: dict[str, int]) -> dict[str, int]:
    """
    Merges two dictionaries, with values from dict2 overriding dict1 for overlapping keys.
    """
    merged_dict: dict[str, int] = {}
    for key, value in dict1.items():
        merged_dict[key] = value
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict

def process_data(data_list: list[dict[str, int]]) -> dict[str, int]:
    """
    Processes a list of dictionaries, merging them sequentially.
    """
    if not data_list:
        return {}

    result: dict[str, int] = data_list[0].copy()
    for i in range(1, len(data_list)):
        result = merge_dictionaries(result, data_list[i])
    return result

def get_keys(input_dict: dict[str, int]) -> list[str]:
    """
    Returns a list of keys from the input dictionary.
    """
    return list(input_dict.keys())

def get_values(input_dict: dict[str, int]) -> list[int]:
    """
    Returns a list of values from the input dictionary.
    """
    return list(input_dict.values())

def count_items(items: list[str]) -> dict[str, int]:
    """
    Counts the occurrences of each item in a list.
    """
    counts: dict[str, int] = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts

