def validate_email(email: str) -> bool:
    if '@' not in email or '.' not in email:
        return False

    parts: list[str] = email.split('@')
    if len(parts) != 2:
        return False

    local_part: str = parts[0]
    domain_part: str = parts[1]

    if not local_part or not domain_part:
        return False

    if '.' not in domain_part:
        return False

    domain_subparts: list[str] = domain_part.split('.')
    if any(not part for part in domain_subparts):
        return False

    at_index: int = email.find('@')
    dot_index: int = email.find('.', at_index)

    return at_index < dot_index and dot_index != -1

def run_tests() -> dict[str, bool]:
    test_cases: list[tuple[str, bool]] = [
        ("test@example.com", True),
        ("invalid-email", False),
        ("a@b.c", True),
        ("@example.com", False),
        ("test@", False),
        ("test.com", False),
        ("test@.com", False),
        ("test@example.", False),
        ("test@example.c", True),
        ("a@b.c.d", True)
    ]

    results: dict[str, bool] = {}
    for email_str, expected in test_cases:
        actual: bool = validate_email(email_str)
        results[email_str] = actual == expected
    return results

if __name__ == '__main__':
    test_results: dict[str, bool] = run_tests()
    for email, passed in test_results.items():
        print(f"'{email}' passed: {passed}")

import math

def circle_area(radius: float) -> float:
    """
    Calculates the area of a circle given its radius.
    """
    if radius < 0:
        raise ValueError("Radius cannot be negative.")
    return math.pi * (radius ** 2)

def main() -> None:
    test_radii: list[float] = [1.0, 0.0, 2.5]
    expected_results: list[float] = [math.pi * (1.0 ** 2), 0.0, math.pi * (2.5 ** 2)]

    for i in range(len(test_radii)):
        radius: float = test_radii[i]
        area: float = circle_area(radius)
        expected: float = expected_results[i]
        print(f"Radius: {radius}, Area: {area}, Expected: {expected}")
        assert abs(area - expected) < 1e-9, f"Test failed for radius {radius}"

    try:
        circle_area(-1.0)
    except ValueError as e:
        print(f"Caught expected error: {e}")

if __name__ == "__main__":
    main()

