import re

def capitalize_sentences(text: str) -> str:
    """Capitalizes the first letter of each sentence in a given text."""

    if not isinstance(text, str):
        raise TypeError("Input must be a string.")

    sentence_enders: list[str] = ['.', '!', '?']
    parts: list[str] = re.split(f'([{re.escape("".join(sentence_enders))}]\\s*)', text)

    result_parts: list[str] = []
    capitalize_next: bool = True

    for i, part in enumerate(parts):
        if capitalize_next and part.strip():
            result_parts.append(part.strip().capitalize())
            capitalize_next = False
        else:
            result_parts.append(part)

        if any(part.endswith(end) for end in sentence_enders):
            capitalize_next = True

    final_string: str = "".join(result_parts)
    return final_string

