from collections import deque

def simulate_queue(operations: list[tuple[str, int | None]]) -> list[int]:
    q: deque[int] = deque()
    for operation, value in operations:
        if operation == 'enqueue':
            if value is not None:
                q.append(value)
        elif operation == 'dequeue':
            if q:
                q.popleft()
    return list(q)

