def most_frequent_char(text: str) -> str:
    char_counts: dict[str, int] = {}
    char_order: list[str] = []

    for char in text:
        if char.isspace():
            continue
        lower_char: str = char.lower()
        if lower_char not in char_counts:
            char_counts[lower_char] = 0
            char_order.append(lower_char)
        char_counts[lower_char] += 1

    if not char_counts:
        return ''

    max_count: int = -1
    most_frequent: str = ''

    for c in char_order:
        current_count: int = char_counts[c]
        if current_count > max_count:
            max_count = current_count
            most_frequent = c
    return most_frequent

