def is_leap_year(year: int) -> bool:
    """
    Determines if a given year is a leap year.

    A leap year is divisible by 4, but not by 100 unless it's also divisible by 400.
    """
    if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
        return True
    return False

def get_leap_years_in_range(start_year: int, end_year: int) -> list[int]:
    """
    Returns a list of leap years within a specified range (inclusive).
    """
    leap_years: list[int] = []
    for year in range(start_year, end_year + 1):
        if is_leap_year(year):
            leap_years.append(year)
    return leap_years

def categorize_years(years: list[int]) -> dict[str, list[int]]:
    """
    Categorizes a list of years into leap and non-leap years.
    """
    categorized: dict[str, list[int]] = {"leap": [], "non_leap": []}
    for year_val in years:
        if is_leap_year(year_val):
            categorized["leap"].append(year_val)
        else:
            categorized["non_leap"].append(year_val)
    return categorized

def count_leap_and_non_leap(years: list[int]) -> tuple[int, int]:
    """
    Counts the number of leap and non-leap years in a given list.
    Returns a tuple (leap_count, non_leap_count).
    """
    leap_count: int = 0
    non_leap_count: int = 0
    for y in years:
        if is_leap_year(y):
            leap_count += 1
        else:
            non_leap_count += 1
    return (leap_count, non_leap_count)

