    normalized_s2: str = _normalize_string(s2)

    if len(normalized_s1) != len(normalized_s2):
        return False

    char_counts1: dict[str, int] = collections.Counter(normalized_s1)
    char_counts2: dict[str, int] = collections.Counter(normalized_s2)

