def decrypt_caesar(text: str, shift: int) -> str:
    decrypted_chars: list[str] = []
    alphabet_size: int = 26
    for char_code in map(ord, text):
        if 'a' <= chr(char_code) <= 'z':
            decrypted_char_code: int = (char_code - ord('a') - shift + alphabet_size) % alphabet_size + ord('a')
            decrypted_chars.append(chr(decrypted_char_code))
        else:
            decrypted_chars.append(chr(char_code))
    return "".join(decrypted_chars)

