def run_length_decode(encoded_string: str) -> str:
    decoded_parts: list[str] = []
    i: int = 0
    while i < len(encoded_string):
        count_str: str = ""
        while i < len(encoded_string) and encoded_string[i].isdigit():
            count_str += encoded_string[i]
            i += 1
        count: int = int(count_str)
        char: str = encoded_string[i]
        decoded_parts.append(char * count)
        i += 1
    return "".join(decoded_parts)

def decimal_to_hex(decimal_num: int) -> str:
    if decimal_num == 0:
        return '0'

    hex_chars: list[str] = []
    hex_map: dict[int, str] = {
        10: 'A', 11: 'B', 12: 'C',
        13: 'D', 14: 'E', 15: 'F'
    }

    current_num: int = decimal_num
    while current_num > 0:
        remainder: int = current_num % 16
        if remainder < 10:
            hex_chars.append(str(remainder))
        else:
            hex_chars.append(hex_map[remainder])
        current_num //= 16

    return "".join(hex_chars[::-1])

