    """Counts the occurrences of a keyword in a text, case-insensitive."""
    lower_text: str = text.lower()
    lower_keyword: str = keyword.lower()

    words: list[str] = []
    current_word_start: int = 0
    for i, char in enumerate(lower_text):
        if not char.isalnum():
            if i > current_word_start:
                words.append(lower_text[current_word_start:i])
            current_word_start = i + 1
    if len(lower_text) > current_word_start:
        words.append(lower_text[current_word_start:])

    count: int = 0
    for word_in_text in words:
        if word_in_text == lower_keyword:
            count += 1

    return count

