def count_char(text: str, char_to_count: str) -> int:
    """
    Counts the total occurrences of a specific character in a given string.

    Args:
        text: The input string to search within.
        char_to_count: The character to count occurrences of.

    Returns:
        The total number of times `char_to_count` appears in `text`.
    """
    if not isinstance(text, str) or not isinstance(char_to_count, str):
        raise TypeError("Both arguments must be strings.")
    if len(char_to_count) != 1:
        raise ValueError("The character to count must be a single character string.")

    count: int = 0
    for char_in_text in text:
        if char_in_text == char_to_count:
            count += 1
    return count

def test_count_char() -> None:
    test_cases: list[tuple[str, str, int]] = [
        ('banana', 'a', 3),
        ('Mississippi', 's', 4),
        ('hello world', 'o', 2),
        ('programming', 'z', 0),
        ('', 'a', 0),
        ('aaaaa', 'a', 5),
        ('bBbB', 'B', 2)
    ]

    for text_input, char_input, expected_output in test_cases:
        actual_output: int = count_char(text_input, char_input)
        assert actual_output == expected_output, \
            f"Input: ('{text_input}', '{char_input}'), Expected: {expected_output}, Got: {actual_output}"

    # Test cases for error handling
    error_cases: list[tuple[str, str]] = [
        ("abc", "ab"),  # char_to_count is not a single character
        ("abc", ""),    # char_to_count is empty
    ]

    for text_val, char_val in error_cases:
        try:
            count_char(text_val, char_val)
            assert False, f"ValueError was not raised for ('{text_val}', '{char_val}')"
        except ValueError:
            pass
        except Exception as e:
            assert False, f"Unexpected error type {type(e)} raised for ('{text_val}', '{char_val}')"

    type_error_cases: list[tuple[object, object]] = [
        (123, 'a'),
        ('abc', 1),
        (True, 'a'),
        ('abc', None)
    ]

    for text_val, char_val in type_error_cases:
        try:
            count_char(text_val, char_val) # type: ignore
            assert False, f"TypeError was not raised for ('{text_val}', '{char_val}')"
        except TypeError:
            pass
        except Exception as e:
            assert False, f"Unexpected error type {type(e)} raised for ('{text_val}', '{char_val}')"

test_count_char()

