def are_anagrams(str1: str, str2: str) -> bool:
    def _normalize(s: str) -> dict[str, int]:
        char_counts: dict[str, int] = {}
        for char in s.lower():
            if 'a' <= char <= 'z':
                char_counts[char] = char_counts.get(char, 0) + 1
        return char_counts

    counts1: dict[str, int] = _normalize(str1)
    counts2: dict[str, int] = _normalize(str2)

    all_keys: list[str] = sorted(list(counts1.keys() | counts2.keys()))

    for key in all_keys:
        if counts1.get(key, 0) != counts2.get(key, 0):
            return False
    return True

