def calculate_sma(data: list[float | int], window_size: int) -> list[float]:
    if not data or window_size <= 0:
        return []
    if window_size > len(data):
        raise ValueError("Window size cannot be greater than the number of data points.")

    sma_values: list[float] = []
    for i in range(len(data) - window_size + 1):
        current_window: list[float | int] = data[i : i + window_size]
        window_sum: float = sum(current_window)
        sma_values.append(window_sum / window_size)

    return sma_values

