import random

def play_guessing_game(target: int, max_guesses: int) -> int:
    guesses_taken: int = 0
    guessed_numbers: list[int] = []

    while guesses_taken < max_guesses:
        guess: int = random.randint(1, 100)
        guesses_taken += 1
        guessed_numbers.append(guess)
        if guess == target:
            return guesses_taken
    return -1

def run_simulations(num_simulations: int, target_value: int, limit_guesses: int) -> dict[str, float]:
    results: list[int] = []
    for _ in range(num_simulations):
        results.append(play_guessing_game(target_value, limit_guesses))

    successful_attempts: list[int] = [r for r in results if r != -1]
    success_rate: float = len(successful_attempts) / num_simulations if num_simulations > 0 else 0.0

    return {"success_rate": success_rate, "average_guesses_on_success": sum(successful_attempts) / len(successful_attempts) if successful_attempts else 0.0}

if __name__ == '__main__':
    simulation_output: dict[str, float] = run_simulations(1000, 50, 10)
    print(simulation_output)

