    parts: list[str] = email_string.split('@')
    if len(parts) != 2:
        return False

    local_part: str = parts[0]
    domain_part: str = parts[1]

    if not local_part or not domain_part:
        return False

    if '.' not in domain_part:
        return False

    domain_segments: list[str] = domain_part.split('.')
    if any(not segment for segment in domain_segments):
        return False

    if domain_part.startswith('.') or domain_part.endswith('.'):
        return False

    return True

