def xor_cipher(text: str, key_char: str) -> str:
    """
    Encrypts or decrypts text using a XOR cipher with a single character key.
    """
    if len(key_char) != 1:
        raise ValueError("Key must be a single character.")

    key_ord: int = ord(key_char)
    result_chars: list[str] = []

    for char_val in text:
        encrypted_ord: int = ord(char_val) ^ key_ord
        result_chars.append(chr(encrypted_ord))

    return "".join(result_chars)

