def is_palindrome_string(s: str) -> bool:
    cleaned_chars: list[str] = [char.lower() for char in s if char.isalnum()]
    left: int = 0
    right: int = len(cleaned_chars) - 1

    while left < right:
        if cleaned_chars[left] != cleaned_chars[right]:
            return False
        left += 1
        right -= 1
    return True

